import React, { useState, useEffect } from 'react'
import SlideBarComponent from '../../components/SlideBar/SlideBarComponent'
import './Homepage.scss'
import EmployeeList from '../../components/EmployeeList/EmployeeList'
import { getAllEmployees } from '../../service/statisticsservice'

const Homepage = () => {
    const [totalEmployees, setTotalEmployees] = useState(0);

    const handleEmployeeCountChange = (count) => {
        setTotalEmployees(count);
    };
    return (
        <div className="container">
            <div className="sidebar">
                <SlideBarComponent />
            </div>

            <div className="content">
                {/* Stat Cards */}
                <div className="top-stats">
                    <div className="stat-card">
                        <p className="stat-label">Tổng nhân viên</p>
                        <p className="stat-value">{totalEmployees}</p>
                    </div>
                </div>

                {/* Employee List */}
                <EmployeeList />
                {/* ... rest of the code ... */}
            </div>
        </div>
    )
}

export default Homepage
